# Let me do a proper BFS to verify the depth levels
from collections import deque

def bfs_depth(graph, start):
    """Return dict mapping node to its shortest distance from start"""
    distances = {start: 0}
    queue = deque([start])

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if neighbor not in distances:
                distances[neighbor] = distances[node] + 1
                queue.append(neighbor)

    return distances

distances = bfs_depth(adj, start)
print(f"Distances from {start}:")
for node, dist in sorted(distances.items()):
    print(f"  {node}: {dist}")

print(f"\nNodes at exactly depth 2: {sorted([n for n, d in distances.items() if d == 2])}")
```

